"""The four observed finding types generated by the original restored portal."""
import hashlib
import json
import math


def findings(source):
    result = []
    context = source.get('context') or {}
    planogram = context.get('planogramAlert') or {}
    if planogram.get('message'):
        result.append(('planogram', str(planogram['message']), planogram))
    empty = source.get('empty_space_pct')
    if isinstance(empty, (int, float)) and math.isfinite(empty) and empty > 0:
        result.append(('empty-space', f'Espacio vacío observado: {empty:g}%', empty))
    products = source.get('products') or []
    no_price = [row for row in products if ('price_clp' in row and row['price_clp'] is None)
                or row.get('has_price_label') is False or row.get('price_visible') is False]
    if no_price:
        result.append(('no-price', f'{len(no_price)} posiciones sin precio visible', no_price))
    absent = [row for row in products if row.get('out_of_stock') is True]
    if absent:
        result.append(('absent', f'{len(absent)} productos reportados ausentes', absent))
    return [{'kind': kind, 'title': title, 'priority': 'Alta' if index == 0 else 'Media', 'owner': 'Sin asignar',
             'fingerprint': hashlib.sha256(json.dumps([kind, evidence], sort_keys=True, ensure_ascii=False).encode()).hexdigest()}
            for index, (kind, title, evidence) in enumerate(result)]


def source_from_reading(reading):
    return {'empty_space_pct': reading['empty_space_pct'], 'products': json.loads(reading['products_json'] or '[]'),
            'context': json.loads(reading['capture_context_json']) if reading['capture_context_json'] else {}}
